// String implements the fmt.Stringer.
func (_m *Project) String() string {
	var builder strings.Builder
	builder.WriteString("Project(")
	builder.WriteString(fmt.Sprintf("id=%v, ", _m.ID))
	if v := _m.DeletedAt; v != nil {
		builder.WriteString("deletedAt=")
		builder.WriteString(v.Format(time.ANSIC))
	}
	builder.WriteString(", ")
	builder.WriteString("name=")
	builder.WriteString(_m.Name)
	builder.WriteString(", ")
	if v := _m.Description; v != nil {
		builder.WriteString("description=")
		builder.WriteString(*v)
	}
	builder.WriteString(", ")
	builder.WriteString("organizationId=")
	builder.WriteString(fmt.Sprintf("%v", _m.OrganizationId))
	builder.WriteString(", ")
	if v := _m.VercelProjectId; v != nil {
		builder.WriteString("vercelProjectId=")
		builder.WriteString(*v)
	}
	builder.WriteString(", ")
	if v := _m.VercelProjectName; v != nil {
		builder.WriteString("vercelProjectName=")
		builder.WriteString(*v)
	}
	builder.WriteString(", ")
	if v := _m.ActiveNativeDeploymentId; v != nil {
		builder.WriteString("activeNativeDeploymentId=")
		builder.WriteString(*v)
	}
	builder.WriteString(", ")
	builder.WriteString("createdAt=")
	builder.WriteString(_m.CreatedAt.Format(time.ANSIC))
	builder.WriteString(", ")
	builder.WriteString("updatedAt=")
	builder.WriteString(_m.UpdatedAt.Format(time.ANSIC))
	builder.WriteByte(')')
	return builder.String()
}

